-- verified: IBM i 7.5 on PUB400 (TR unknown, Db2 PTF Group unknown), Django 6.0.9, 2026-10-31
INSERT INTO "TESTAPP_AUTHOR" ("ID", "NAME") VALUES (%s, %s);
MERGE INTO "TESTAPP_BOOK" AS TGT USING (VALUES (CAST(%s AS BIGINT), CAST(%s AS INTEGER), CAST(%s AS NVARCHAR(200)), CAST(%s AS TIMESTAMP(6)), CAST(%s AS TIME), CAST(%s AS BOOLEAN), CAST(%s AS INTEGER)), (CAST(%s AS BIGINT), CAST(%s AS INTEGER), CAST(%s AS NVARCHAR(200)), CAST(%s AS TIMESTAMP(6)), CAST(%s AS TIME), CAST(%s AS BOOLEAN), CAST(%s AS INTEGER))) AS SRC ("ID", "AUTHOR_ID", "TITLE", "PUBLISHED", "READING_TIME", "AVAILABLE", "PAGES") ON (TGT."ID" = SRC."ID") WHEN MATCHED THEN UPDATE SET TGT."TITLE" = SRC."TITLE", TGT."PAGES" = SRC."PAGES" WHEN NOT MATCHED THEN INSERT ("ID", "AUTHOR_ID", "TITLE", "PUBLISHED", "READING_TIME", "AVAILABLE", "PAGES") VALUES (SRC."ID", SRC."AUTHOR_ID", SRC."TITLE", SRC."PUBLISHED", SRC."READING_TIME", SRC."AVAILABLE", SRC."PAGES");
